-- Itens de campo (moedas e caixas) do JP 983: pontos onde podem nascer, por curso e buraco físico.
-- Aprendidos das tacadas (onde a bola parou, como o CoinCubeLocationUpdateSystem do GB) e o seed abaixo, do dump do GB
-- (Server/SQL/bk-schema-mssql-complet2022.sql, tabela pangya_coin_cube_location): o Wiz City inteiro (curso 19, 355
-- pontos) e os pontos de chão aprendidos no Shining Sand (curso 10; 24 linhas, 23 distintas). As outras linhas do dump eram cópias do Wiz City
-- em todos os cursos (mesmas coordenadas): não servem e ficaram de fora.
create table field_spots (
    course     smallint not null,                -- mapa (Course.iff)
    hole       smallint not null,                -- número do buraco no mapa (1..18)
    type       smallint not null,                -- 0 moeda, 1 caixa
    location   smallint not null,                -- tipo_location do GB: 0 borda do green, 1 carpete, 2 ar, 3 chão
    x          real not null,
    y          real not null,
    z          real not null,
    hits       int not null default 1,           -- quantas bolas pararam ali (rate do GB)
    par        smallint not null default 0,      -- par do buraco (0 = desconhecido)
    updated_at timestamptz not null default now(),
    primary key (course, hole, type, x, y, z)
);

on conflict do nothing;
